{
  "references": [
    {
      "id": "R1",
      "summary_ko": "스쿠터가 넘어질 때 바퀴가 지면을 뚫고 들어가는 것처럼 보임"
    },
    {
      "id": "R2",
      "summary_ko": "스쿠터 뒷바퀴가 지면 속으로 파고들어 뚫리는 것처럼 보임"
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "영상 특징 및 픽셀 구조 변화에 따른 형태·존재 변화 가능성 측정 제안"
    },
    {
      "id": "C2",
      "summary_ko": "넘어지는 동안 스쿠터 구조가 비정상적으로 늘어나고 뒤틀리며 위치가 불안정하게 변함"
    },
    {
      "id": "C3",
      "summary_ko": "탑승자가 잔디 위로 넘어질 때 스쿠터 구조가 기형적으로 변형되고 늘어남"
    },
    {
      "id": "C4",
      "summary_ko": "넘어지는 동안 탑승자의 다리와 발이 스쿠터 발판 및 지면에 부자연스럽게 미끄러지거나 분리·재부착됨"
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "구체적 대상이 식별되지 않은 일반적인 측정 제안으로, 지면 클리핑 현상과 동일한지 판단하기에 정보가 부족합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "참조는 바퀴가 지면을 뚫고 들어가는 현상을 다루지만, 후보는 스쿠터 프레임 전체의 늘어남 및 뒤틀림 변형을 설명합니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "참조는 바퀴의 지면 관통 결함이고, 후보는 스쿠터 구조의 형태 변형 및 늘어남 결함을 다룹니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "참조는 스쿠터 바퀴를 대상으로 하나 후보는 탑승자의 다리와 발의 분리 및 미끄러짐을 대상으로 합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "uncertain",
      "reason_ko": "대상이 명시되지 않은 단순 픽셀 변화 측정 가설로, 뒷바퀴의 지면 관통 결함과의 연관성을 단정할 수 없습니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "참조는 뒷바퀴의 지면 뚫림을 설명하지만, 후보는 스쿠터 프레임 구조의 왜곡 및 뒤틀림을 다룹니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "참조는 뒷바퀴의 지면 관통 문제이며, 후보는 스쿠터 구조 전반의 부자연스러운 변형을 지적합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "스쿠터 뒷바퀴의 지면 관통과 탑승자의 다리/발 미끄러짐 및 분리 현상은 서로 다른 대상과 결함입니다."
    }
  ]
}
